			path := "/v1/packages/delete-multiple"

			// Build query string
			var queryParts []string
			if len(queryParts) > 0 {
				path = path + "?" + strings.Join(queryParts, "&")
			}

			// Make request
			// Read body from stdin if available
			var body io.Reader
			// Handle --ids flag for bulk operations
			if len(flagIds) > 0 {
				payload := struct {
					IDs []string `json:"ids"`
				}{IDs: flagIds}
				idsJSON, err := json.Marshal(payload)
				if err != nil {
					return fmt.Errorf("encoding ids: %w", err)
				}
				body = strings.NewReader(string(idsJSON))
			} else {
				stat, _ := os.Stdin.Stat()
				if (stat.Mode() & os.ModeCharDevice) == 0 {
					body = os.Stdin
				}
			}
			resp, err := ctx.Client.Do(reqCtx, "POST", path, body)
			if err != nil {
				return err
			}
			defer resp.Body.Close()

			err = ctx.Output.PrintResponse(resp)
