func newPackagesUploadCmd(ctx *registry.CLIContext) *cobra.Command {
	var (
		flagFile string
		flagName string
	)

	cmd := &cobra.Command{
		Use:   "upload [<id>]",
		Short: "Add a manifest to a package",
		Long:  "Add a manifest to a package",
		Args:  cobra.MaximumNArgs(1),
		RunE: func(cmd *cobra.Command, args []string) error {
			reqCtx := cmd.Context()

			// Resolve resource ID from positional arg, --name, or lookup flags
			var resolvedID string
			if flagName != "" {
				rid, err := resolveNameToID(reqCtx, ctx.Client, "/v1/packages", "packageName", "id", flagName)
				if err != nil {
					return err
				}
				resolvedID = rid
			} else if len(args) > 0 {
				resolvedID = args[0]
			} else {
				return fmt.Errorf("provide an <id> argument, --name")
			}

			// Build request path
			path := "/v1/packages/{id}/manifest"
			path = strings.Replace(path, "{id}", url.PathEscape(resolvedID), 1)

			// Build query string
			var queryParts []string
			if len(queryParts) > 0 {
				path = path + "?" + strings.Join(queryParts, "&")
			}

			// Make request
			if ctx.Uploader == nil {
				return fmt.Errorf("file upload not supported in this context")
			}
			f, err := os.Open(flagFile)
			if err != nil {
				return fmt.Errorf("opening %s: %w", flagFile, err)
			}
			defer f.Close()
			// Stream the file through a seekable multipart body so Upload can
			// precompute Content-Length and retry on HTTP 429 without
			// re-buffering the file.
			body, contentType, contentLength, err := client.NewMultipartFileUpload("file", f)
			if err != nil {
				return fmt.Errorf("building multipart body: %w", err)
			}
			resp, err := ctx.Uploader.Upload(reqCtx, path, body, contentType, contentLength)
			if err != nil {
				return err
			}
			defer resp.Body.Close()

			return ctx.Output.PrintResponse(resp)
		},
	}

	cmd.Flags().StringVar(&flagFile, "file", "", "Path to file to upload (required)")
	_ = cmd.MarkFlagRequired("file")
	cmd.Flags().StringVar(&flagName, "name", "", "Look up package by name")

	return cmd
}

